// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());

        address originalOwner = c.owner();

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        if (success) {
            assertEq(c.owner(), originalOwner, "Owner should not change for non-admin caller");
        }
    }
}
